  }

  void _onItemTapped(int index) {
    setState(() {
      _selectedIndex = index;
    });
  }

  void _refreshAll() {
    // Обновляем только текущую страницу (если это CurrencyListPage или NewsListPage)
    if (_selectedIndex == 0 || _selectedIndex == 1) {
      setState(() {
        // Генерируем новый ключ для текущей страницы, чтобы Flutter её пересоздал
        _pageKeys[_selectedIndex] = ValueKey(DateTime.now().millisecondsSinceEpoch);
